page Simulacion "/" {
  ref box
  ref balls
  ref raf
  state paused = false
  state count = 5
  state frames = 0

  fn newBall() {
    return {
      x: 10 + Math.random() * 380,
      y: 10 + Math.random() * 280,
      vx: (Math.random() - 0.5) * 6,
      vy: (Math.random() - 0.5) * 6,
      r: 10
    }
  }

  fn makeBalls(n) {
    let arr = []
    for (let i = 0; i < n; i++) {
      arr.push(newBall())
    }
    return arr
  }

  fn draw() {
    let ctx = box.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#e11d48"
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn step() {
    let bs = balls
    for (let i = 0; i < bs.length; i++) {
      let b = bs[i]
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      if (b.x < b.r) { b.x = b.r; b.vx = Math.abs(b.vx) }
      if (b.x > 400 - b.r) { b.x = 400 - b.r; b.vx = -Math.abs(b.vx) }
      if (b.y < b.r) { b.y = b.r; b.vy = Math.abs(b.vy) }
      if (b.y > 300 - b.r) { b.y = 300 - b.r; b.vy = -Math.abs(b.vy) }
    }
    for (let i = 0; i < bs.length; i++) {
      for (let j = i + 1; j < bs.length; j++) {
        let a = bs[i]
        let c = bs[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let d = Math.hypot(dx, dy)
        let min = a.r + c.r
        if (d < min) {
          let tx = a.vx
          let ty = a.vy
          a.vx = c.vx
          a.vy = c.vy
          c.vx = tx
          c.vy = ty
          if (d > 0) {
            let o = (min - d) / 2
            let nx = dx / d
            let ny = dy / d
            a.x -= nx * o
            a.y -= ny * o
            c.x += nx * o
            c.y += ny * o
          } else {
            c.x += 1
          }
          for (let k = 0; k < 2; k++) {
            let p = k == 0 ? a : c
            if (p.x < p.r) { p.x = p.r }
            if (p.x > 400 - p.r) { p.x = 400 - p.r }
            if (p.y < p.r) { p.y = p.r }
            if (p.y > 300 - p.r) { p.y = 300 - p.r }
          }
        }
      }
    }
    draw()
    frames++
    raf = requestAnimationFrame(step)
  }

  fn add() {
    balls.push(newBall())
    count = balls.length
    if (paused) { draw() }
  }

  fn toggle() {
    if (paused) {
      paused = false
      raf = requestAnimationFrame(step)
    } else {
      paused = true
      cancelAnimationFrame(raf)
    }
  }

  fn restart() {
    balls = makeBalls(5)
    count = 5
    frames = 0
    draw()
  }

  mount {
    balls = makeBalls(5)
    count = 5
    draw()
    raf = requestAnimationFrame(step)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    title "Simulación de pelotas"
    canvas ref=box id="sim" width=400 height=300 style="border:1px solid #ccc"
    row gap=2 {
      button "Agregar" primary -> add()
      button `${paused ? "Reanudar" : "Pausar"}` -> toggle()
      button "Reiniciar" danger -> restart()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

