  state count = 5
  state frames = 0
  state paused = false

  ref box
  ref balls
  ref raf

  fn spawn() {
    return {
      x: 10 + Math.random() * 380,
      y: 10 + Math.random() * 280,
      vx: (Math.random() - 0.5) * 6,
      vy: (Math.random() - 0.5) * 6,
      r: 10,
      color: `hsl(${Math.floor(Math.random() * 360)}, 70%, 50%)`
    }
  }

  fn draw() {
    let ctx = box.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fillStyle = b.color
      ctx.fill()
    }
  }

  fn step() {
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      if (b.x < b.r) { b.x = b.r; b.vx = -b.vx }
      if (b.x > 400 - b.r) { b.x = 400 - b.r; b.vx = -b.vx }
      if (b.y < b.r) { b.y = b.r; b.vy = -b.vy }
      if (b.y > 300 - b.r) { b.y = 300 - b.r; b.vy = -b.vy }
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let b = balls[j]
        let dx = b.x - a.x
        let dy = b.y - a.y
        let dist = Math.sqrt(dx * dx + dy * dy)
        let minD = a.r + b.r
        if (dist < minD) {
          if (dist == 0) { dx = 1; dy = 0; dist = 1 }
          let nx = dx / dist
          let ny = dy / dist
          let overlap = (minD - dist) / 2
          a.x -= nx * overlap
          a.y -= ny * overlap
          b.x += nx * overlap
          b.y += ny * overlap
          let van = a.vx * nx + a.vy * ny
          let vbn = b.vx * nx + b.vy * ny
          if (van - vbn > 0) {
            let d = vbn - van
            a.vx += d * nx
            a.vy += d * ny
            b.vx -= d * nx
            b.vy -= d * ny
          }
        }
      }
    }
    for (let i = 0; i < balls.length; i++) {
      let b = balls[i]
      if (b.x < b.r) { b.x = b.r }
      if (b.x > 400 - b.r) { b.x = 400 - b.r }
      if (b.y < b.r) { b.y = b.r }
      if (b.y > 300 - b.r) { b.y = 300 - b.r }
    }
  }

  fn tick() {
    step()
    draw()
    frames++
    raf = requestAnimationFrame(tick)
  }

  fn reset() {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push(spawn())
    }
    count = balls.length
    frames = 0
    draw()
  }

  fn add() {
    balls.push(spawn())
    count = balls.length
  }

  fn toggle() {
    if paused {
      paused = false
      raf = requestAnimationFrame(tick)
    } else {
      paused = true
      cancelAnimationFrame(raf)
    }
  }

  mount {
    reset()
    raf = requestAnimationFrame(tick)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 {
    canvas ref=box id="sim" width=400 height=300 style="border:1px solid #888"
    row gap=2 {
      button "Agregar" primary -> add()
      button `${paused ? "Reanudar" : "Pausar"}` -> toggle()
      button "Reiniciar" danger -> reset()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

