import { useEffect, useRef, useState } from "react";

type Ball = { x: number; y: number; vx: number; vy: number; r: number };

const W = 400;
const H = 300;
const R = 10;
const G = 0.2;

const rand = (a: number, b: number) => a + Math.random() * (b - a);

const makeBall = (): Ball => {
  const speed = rand(1, 4);
  const angle = rand(0, Math.PI * 2);
  return {
    x: rand(R, W - R),
    y: rand(R, H - R),
    vx: Math.cos(angle) * speed,
    vy: Math.sin(angle) * speed,
    r: R,
  };
};

const makeBalls = (n: number): Ball[] =>
  Array.from({ length: n }, makeBall);

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballsRef = useRef<Ball[]>(makeBalls(5));
  const framesRef = useRef(0);
  const pausedRef = useRef(false);

  const [count, setCount] = useState(5);
  const [frames, setFrames] = useState(0);
  const [paused, setPaused] = useState(false);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    let raf = 0;

    const draw = () => {
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = "#111827";
      ctx.fillRect(0, 0, W, H);
      ballsRef.current.forEach((b, i) => {
        ctx.beginPath();
        ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
        ctx.fillStyle = `hsl(${(i * 67) % 360}, 80%, 60%)`;
        ctx.fill();
      });
    };

    const step = () => {
      const balls = ballsRef.current;
      for (const b of balls) {
        b.vy += G;
        b.x += b.vx;
        b.y += b.vy;
        if (b.x - b.r < 0) {
          b.x = b.r;
          b.vx = Math.abs(b.vx);
        } else if (b.x + b.r > W) {
          b.x = W - b.r;
          b.vx = -Math.abs(b.vx);
        }
        if (b.y - b.r < 0) {
          b.y = b.r;
          b.vy = Math.abs(b.vy);
        } else if (b.y + b.r > H) {
          b.y = H - b.r;
          b.vy = -Math.abs(b.vy);
        }
      }
      for (let i = 0; i < balls.length; i++) {
        for (let j = i + 1; j < balls.length; j++) {
          const a = balls[i];
          const c = balls[j];
          const dx = c.x - a.x;
          const dy = c.y - a.y;
          const minD = a.r + c.r;
          const d2 = dx * dx + dy * dy;
          if (d2 < minD * minD) {
            let d = Math.sqrt(d2);
            let nx: number;
            let ny: number;
            if (d === 0) {
              nx = 1;
              ny = 0;
              d = 0;
            } else {
              nx = dx / d;
              ny = dy / d;
            }
            // separar
            const overlap = (minD - d) / 2;
            a.x -= nx * overlap;
            a.y -= ny * overlap;
            c.x += nx * overlap;
            c.y += ny * overlap;
            // mantener dentro del canvas
            for (const b of [a, c]) {
              b.x = Math.min(Math.max(b.x, b.r), W - b.r);
              b.y = Math.min(Math.max(b.y, b.r), H - b.r);
            }
            // intercambio de velocidades (masas iguales) a lo largo de la normal
            const rvx = a.vx - c.vx;
            const rvy = a.vy - c.vy;
            const vn = rvx * nx + rvy * ny;
            if (vn > 0) {
              a.vx -= vn * nx;
              a.vy -= vn * ny;
              c.vx += vn * nx;
              c.vy += vn * ny;
            }
          }
        }
      }
    };

    const loop = () => {
      if (!pausedRef.current) {
        step();
        draw();
        framesRef.current += 1;
        setFrames(framesRef.current);
      }
      raf = requestAnimationFrame(loop);
    };

    draw();
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, []);

  const add = () => {
    ballsRef.current.push(makeBall());
    setCount(ballsRef.current.length);
  };

  const togglePause = () => {
    pausedRef.current = !pausedRef.current;
    setPaused(pausedRef.current);
  };

  const reset = () => {
    ballsRef.current = makeBalls(5);
    framesRef.current = 0;
    setCount(5);
    setFrames(0);
  };

  const btn =
    "px-3 py-1 rounded bg-indigo-600 text-white hover:bg-indigo-500 active:bg-indigo-700";

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col items-center gap-3 p-4">
      <canvas
        id="sim"
        ref={canvasRef}
        width={W}
        height={H}
        className="border border-gray-400 rounded shadow"
      />
      <div className="flex gap-2">
        <button className={btn} onClick={add}>
          Agregar
        </button>
        <button className={btn} onClick={togglePause}>
          {paused ? "Reanudar" : "Pausar"}
        </button>
        <button className={btn} onClick={reset}>
          Reiniciar
        </button>
      </div>
      <div className="flex gap-6 text-gray-800 font-mono">
        <span>Pelotas: {count}</span>
        <span>Cuadros: {frames}</span>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from "react";

const W = 400;
const H = 300;
const R = 10;
const G = 0.2;

type Ball = { x: number; y: number; vx: number; vy: number };

const rand = (a: number, b: number) => a + Math.random() * (b - a);

const makeBall = (): Ball => {
  let vx = rand(-3, 3);
  if (Math.abs(vx) < 0.5) vx = vx < 0 ? -1 : 1;
  return {
    x: rand(R, W - R),
    y: rand(R, H - R),
    vx,
    vy: rand(-3, 3),
  };
};

const makeBalls = (n: number): Ball[] =>
  Array.from({ length: n }, makeBall);

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ballsRef = useRef<Ball[]>(makeBalls(5));
  const framesRef = useRef(0);
  const pausedRef = useRef(false);

  const [count, setCount] = useState(5);
  const [frames, setFrames] = useState(0);
  const [paused, setPaused] = useState(false);

  useEffect(() => {
    pausedRef.current = paused;
  }, [paused]);

  useEffect(() => {
    const canvas = canvasRef.current!;
    const ctx = canvas.getContext("2d")!;
    let raf = 0;

    const step = () => {
      const balls = ballsRef.current;

      for (const b of balls) {
        b.vy += G;
        b.x += b.vx;
        b.y += b.vy;
        if (b.x < R) {
          b.x = R;
          b.vx = Math.abs(b.vx);
        } else if (b.x > W - R) {
          b.x = W - R;
          b.vx = -Math.abs(b.vx);
        }
        if (b.y < R) {
          b.y = R;
          b.vy = Math.abs(b.vy);
        } else if (b.y > H - R) {
          b.y = H - R;
          b.vy = -Math.abs(b.vy);
        }
      }

      for (let i = 0; i < balls.length; i++) {
        for (let j = i + 1; j < balls.length; j++) {
          const a = balls[i];
          const b = balls[j];
          let dx = b.x - a.x;
          let dy = b.y - a.y;
          let d = Math.hypot(dx, dy);
          if (d < 2 * R) {
            if (d === 0) {
              dx = 1;
              dy = 0;
              d = 1;
            }
            const nx = dx / d;
            const ny = dy / d;
            // separar
            const overlap = (2 * R - d) / 2;
            a.x -= nx * overlap;
            a.y -= ny * overlap;
            b.x += nx * overlap;
            b.y += ny * overlap;
            // mantener dentro del canvas
            for (const p of [a, b]) {
              p.x = Math.min(W - R, Math.max(R, p.x));
              p.y = Math.min(H - R, Math.max(R, p.y));
            }
            // intercambio de velocidades si se acercan (masas iguales)
            const rvx = a.vx - b.vx;
            const rvy = a.vy - b.vy;
            const vn = rvx * nx + rvy * ny;
            if (vn > 0) {
              a.vx -= vn * nx;
              a.vy -= vn * ny;
              b.vx += vn * nx;
              b.vy += vn * ny;
            }
          }
        }
      }
    };

    const draw = () => {
      ctx.clearRect(0, 0, W, H);
      ctx.fillStyle = "#111827";
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = "#38bdf8";
      for (const b of ballsRef.current) {
        ctx.beginPath();
        ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
        ctx.fill();
      }
    };

    const loop = () => {
      if (!pausedRef.current) {
        step();
        draw();
        framesRef.current += 1;
        setFrames(framesRef.current);
      }
      raf = requestAnimationFrame(loop);
    };

    draw();
    raf = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(raf);
  }, []);

  const add = () => {
    ballsRef.current.push(makeBall());
    setCount(ballsRef.current.length);
  };

  const reset = () => {
    ballsRef.current = makeBalls(5);
    framesRef.current = 0;
    setCount(5);
    setFrames(0);
  };

  const btn =
    "px-3 py-1 rounded bg-sky-600 text-white hover:bg-sky-500 active:bg-sky-700";

  return (
    <div className="min-h-screen flex flex-col items-center justify-center gap-3 bg-gray-100 p-4">
      <canvas
        id="sim"
        ref={canvasRef}
        width={W}
        height={H}
        className="border border-gray-400 rounded"
      />
      <div className="flex gap-2">
        <button className={btn} onClick={add}>
          Agregar
        </button>
        <button className={btn} onClick={() => setPaused((p) => !p)}>
          {paused ? "Reanudar" : "Pausar"}
        </button>
        <button className={btn} onClick={reset}>
          Reiniciar
        </button>
      </div>
      <div className="flex gap-4 text-gray-800">
        <span>Pelotas: {count}</span>
        <span>Cuadros: {frames}</span>
