import { createSignal, onCleanup, onMount } from "solid-js";

const W = 400;
const H = 300;
const R = 10;

type Ball = { x: number; y: number; vx: number; vy: number };

const randomBall = (): Ball => {
  const angle = Math.random() * Math.PI * 2;
  const speed = 1 + Math.random() * 3;
  return {
    x: R + Math.random() * (W - 2 * R),
    y: R + Math.random() * (H - 2 * R),
    vx: Math.cos(angle) * speed,
    vy: Math.sin(angle) * speed,
  };
};

const createBalls = (n: number): Ball[] =>
  Array.from({ length: n }, () => randomBall());

export default function App() {
  let canvas!: HTMLCanvasElement;
  let balls: Ball[] = createBalls(5);
  let raf = 0;
  let paused = false;
  let frames = 0;

  const [count, setCount] = createSignal(5);
  const [frameCount, setFrameCount] = createSignal(0);
  const [isPaused, setIsPaused] = createSignal(false);

  const draw = () => {
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = "#111827";
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = "#38bdf8";
    for (const b of balls) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
      ctx.fill();
    }
  };

  const step = () => {
    for (const b of balls) {
      b.vy += 0.2;
      b.x += b.vx;
      b.y += b.vy;
      if (b.x < R) {
        b.x = R;
        b.vx = Math.abs(b.vx);
      } else if (b.x > W - R) {
        b.x = W - R;
        b.vx = -Math.abs(b.vx);
      }
      if (b.y < R) {
        b.y = R;
        b.vy = Math.abs(b.vy);
      } else if (b.y > H - R) {
        b.y = H - R;
        b.vy = -Math.abs(b.vy);
      }
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i];
        const b = balls[j];
        let dx = b.x - a.x;
        let dy = b.y - a.y;
        let d = Math.hypot(dx, dy);
        if (d < 2 * R) {
          if (d === 0) {
            dx = 1;
            dy = 0;
            d = 1;
          }
          const nx = dx / d;
          const ny = dy / d;
          // separar para que no queden solapadas
          const overlap = (2 * R - d) / 2;
          a.x -= nx * overlap;
          a.y -= ny * overlap;
          b.x += nx * overlap;
          b.y += ny * overlap;
          // intercambio de velocidades
          const tvx = a.vx;
          const tvy = a.vy;
          a.vx = b.vx;
          a.vy = b.vy;
          b.vx = tvx;
          b.vy = tvy;
          // mantener dentro del canvas tras separar
          for (const p of [a, b]) {
            p.x = Math.min(W - R, Math.max(R, p.x));
            p.y = Math.min(H - R, Math.max(R, p.y));
          }
        }
      }
    }
  };

  const loop = () => {
    if (paused) return;
    step();
    draw();
    frames++;
    setFrameCount(frames);
    raf = requestAnimationFrame(loop);
  };

  const add = () => {
    balls.push(randomBall());
    setCount(balls.length);
    if (paused) draw();
  };

  const togglePause = () => {
    paused = !paused;
    setIsPaused(paused);
    if (!paused) {
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(loop);
    } else {
      cancelAnimationFrame(raf);
    }
  };

  const reset = () => {
    balls = createBalls(5);
    frames = 0;
    setCount(5);
    setFrameCount(0);
    draw();
  };

  onMount(() => {
    draw();
    raf = requestAnimationFrame(loop);
  });
  onCleanup(() => cancelAnimationFrame(raf));

  return (
    <div class="min-h-screen bg-gray-900 text-white flex flex-col items-center gap-4 p-6">
      <canvas
        id="sim"
        ref={canvas}
        width={W}
        height={H}
        class="border border-gray-600 rounded"
      />
      <div class="flex gap-2">
        <button class="px-3 py-1 rounded bg-sky-600 hover:bg-sky-500" onClick={add}>
          Agregar
        </button>
        <button class="px-3 py-1 rounded bg-amber-600 hover:bg-amber-500" onClick={togglePause}>
          {isPaused() ? "Reanudar" : "Pausar"}
        </button>
        <button class="px-3 py-1 rounded bg-rose-600 hover:bg-rose-500" onClick={reset}>
          Reiniciar
        </button>
      </div>
      <div class="flex gap-6 text-lg">
        <span>Pelotas: {count()}</span>
        <span>Cuadros: {frameCount()}</span>
      </div>
    </div>
  );
}

import { createSignal, onCleanup, onMount } from "solid-js";

const W = 400;
const H = 300;
const R = 10;

type Ball = { x: number; y: number; vx: number; vy: number; color: string };

const colors = ["#ef4444", "#3b82f6", "#22c55e", "#eab308", "#a855f7", "#f97316", "#14b8a6"];

function randomBall(): Ball {
  return {
    x: R + Math.random() * (W - 2 * R),
    y: R + Math.random() * (H - 2 * R),
    vx: (Math.random() - 0.5) * 8,
    vy: (Math.random() - 0.5) * 8,
    color: colors[Math.floor(Math.random() * colors.length)],
  };
}

function createBalls(n: number): Ball[] {
  return Array.from({ length: n }, randomBall);
}

export default function App() {
  let canvas!: HTMLCanvasElement;
  let balls: Ball[] = createBalls(5);
  let paused = false;
  let raf = 0;

  const [count, setCount] = createSignal(5);
  const [frames, setFrames] = createSignal(0);
  const [isPaused, setIsPaused] = createSignal(false);

  const step = () => {
    for (const b of balls) {
      b.vy += 0.2;
      b.x += b.vx;
      b.y += b.vy;
      if (b.x < R) { b.x = R; b.vx = Math.abs(b.vx); }
      if (b.x > W - R) { b.x = W - R; b.vx = -Math.abs(b.vx); }
      if (b.y < R) { b.y = R; b.vy = Math.abs(b.vy); }
      if (b.y > H - R) { b.y = H - R; b.vy = -Math.abs(b.vy); }
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        const a = balls[i];
        const b = balls[j];
        let dx = b.x - a.x;
        let dy = b.y - a.y;
        let d = Math.hypot(dx, dy);
        if (d < 2 * R) {
          if (d === 0) { dx = 1; dy = 0; d = 1; }
          const nx = dx / d;
          const ny = dy / d;
          const overlap = 2 * R - d;
          a.x -= (nx * overlap) / 2;
          a.y -= (ny * overlap) / 2;
          b.x += (nx * overlap) / 2;
          b.y += (ny * overlap) / 2;
          // mantener dentro del canvas
          for (const p of [a, b]) {
            p.x = Math.min(W - R, Math.max(R, p.x));
            p.y = Math.min(H - R, Math.max(R, p.y));
          }
          // intercambio de velocidades
          const tvx = a.vx, tvy = a.vy;
          a.vx = b.vx; a.vy = b.vy;
          b.vx = tvx; b.vy = tvy;
        }
      }
    }
  };

  const draw = () => {
    const ctx = canvas.getContext("2d")!;
    ctx.clearRect(0, 0, W, H);
    for (const b of balls) {
      ctx.beginPath();
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2);
      ctx.fillStyle = b.color;
      ctx.fill();
    }
  };

  const loop = () => {
    if (!paused) {
      step();
      draw();
      setFrames((f) => f + 1);
    }
    raf = requestAnimationFrame(loop);
  };

  onMount(() => {
    draw();
    raf = requestAnimationFrame(loop);
  });
  onCleanup(() => cancelAnimationFrame(raf));

  const add = () => {
    balls.push(randomBall());
    setCount(balls.length);
    if (paused) draw();
  };

  const togglePause = () => {
    paused = !paused;
    setIsPaused(paused);
  };

  const reset = () => {
    balls = createBalls(5);
    setCount(5);
    setFrames(0);
    draw();
  };

  const btn = "px-3 py-1 rounded bg-blue-600 text-white hover:bg-blue-700";

  return (
    <div class="p-4 flex flex-col items-center gap-3">
      <canvas
        id="sim"
        ref={canvas}
        width={W}
        height={H}
        class="border border-gray-400 bg-white"
      />
      <div class="flex gap-2">
        <button class={btn} onClick={add}>Agregar</button>
        <button class={btn} onClick={togglePause}>
          {isPaused() ? "Reanudar" : "Pausar"}
        </button>
        <button class={btn} onClick={reset}>Reiniciar</button>
      </div>
      <div class="flex gap-4">
        <span>Pelotas: {count()}</span>
        <span>Cuadros: {frames()}</span>
      </div>
    </div>
  );
}
